code.en:
Sentry.init({
  app,
  dsn: dsnFromRuntimeConfig, // not a VITE_ secret in the JS
  release: import.meta.env.VITE_COMMIT_SHA, // must match GitOps digest
  environment: "production",
  tracesSampleRate: 0.15,
  replaysOnErrorSampleRate: 1,
  beforeSend(event) {
    if (event.tags?.http_status === "401") return null
    return scrubPii(event) // strip email, token, order payload
  },
})

