function report(m: { name: string; value: number; id: string }) {
  sendToRum({ ...m, route: route.name, release: SHA, flag: flags.checkout_v2 })
}
onINP(report) // field, not FID
onLCP(report)
onCLS(report)
// alert p75 week-over-week on /checkout, not a site-wide average

